namespace MoriDesk {
 internal static class CanvasProjectGalleryTests {
  static byte[] Png(int width,int height,Color color){var pixels=new byte[width*height*4];for(int i=0;i<pixels.Length;i+=4){pixels[i]=color.B;pixels[i+1]=color.G;pixels[i+2]=color.R;pixels[i+3]=255;}var bitmap=BitmapSource.Create(width,height,96,96,PixelFormats.Bgra32,null,pixels,width*4);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=new MemoryStream()){encoder.Save(stream);return stream.ToArray();}}
  static string Url(byte[] bytes){return "data:image/png;base64,"+Convert.ToBase64String(bytes);}
  static bool HasColor(BitmapSource bitmap,Func<byte,byte,byte,bool> color){var converted=new FormatConvertedBitmap(bitmap,PixelFormats.Bgra32,null,0);var pixels=new byte[converted.PixelWidth*converted.PixelHeight*4];converted.CopyPixels(pixels,converted.PixelWidth*4,0);for(int i=0;i<pixels.Length;i+=4)if(color(pixels[i+2],pixels[i+1],pixels[i]))return true;return false;}
  static bool Reject(Action action){try{action();return false;}catch(InvalidDataException){return true;}catch(IOException){return true;}}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=MatureCanvasStore.MaximumSceneBytes*2,RecursionLimit=48};}
  static Dictionary<string,object> Map(params object[] values){var map=new Dictionary<string,object>();for(int i=0;i<values.Length;i+=2)map.Add((string)values[i],values[i+1]);return map;}
  static Dictionary<string,object> Obj(object value){return (Dictionary<string,object>)value;}
  static object Reversed(object value){var map=value as Dictionary<string,object>;if(map!=null)return map.Reverse().ToDictionary(pair=>pair.Key,pair=>Reversed(pair.Value));var array=value as object[];return array==null?value:array.Select(Reversed).ToArray();}
  static void Render(FrameworkElement element,double width){element.Measure(new Size(width,700));element.Arrange(new Rect(0,0,width,700));element.UpdateLayout();}
  static void Evidence(CanvasProjectsPage page,FreeCanvasStore store,MatureCanvasStore mature,string file){
   Render(page,900);foreach(var row in page.ProjectsForTests){var grid=(Grid)page.ProjectButtonForTests(row.Id).Content;var image=grid.Children.OfType<Grid>().SelectMany(g=>g.Children.OfType<CanvasProjectThumbnailImage>()).SingleOrDefault();if(image!=null)image.Source=CanvasProjectThumbnail.Read(store,mature,row);}var bitmap=new RenderTargetBitmap(900,700,96,96,PixelFormats.Pbgra32);bitmap.Render(page);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(file))encoder.Save(output);
  }
  internal static void Run(string root,Action<bool,string> check){
   Directory.CreateDirectory(root);var app=Application.Current??new Application();var store=new FreeCanvasStore(Path.Combine(root,"profile"));var mature=new MatureCanvasStore(Path.Combine(root,"profile"));
   var board=store.Create("机器人参考");string original=Path.Combine(root,"original.png");File.WriteAllBytes(original,Png(120,80,Colors.Crimson));var sourceBytes=File.ReadAllBytes(original);var sourceTime=File.GetLastWriteTimeUtc(original);var picture=store.Import(board.Id,original,CancellationToken.None);picture.X=40;picture.Y=80;board.Items.Add(picture);board.Items.Add(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="line",X=180,Y=40,EndX=300,EndY=160,Stroke=5,Color="#0000FF"});board.Items.Add(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="text",Text="方案 A",X=10,Y=0,Width=160,Height=35,FontSize=24,Color="#000000"});store.Save(board);
   string manifest=Path.Combine(store.Root,board.Id,"project.json");byte[] before=File.ReadAllBytes(manifest);var thumb=CanvasProjectThumbnail.RenderLegacy(store,board);
   check(thumb!=null&&thumb.PixelWidth==320&&thumb.PixelHeight==200&&thumb.IsFrozen,"legacy project preview is a frozen, card-sized actual board rendering");
   check(HasColor(thumb,(r,g,b)=>r>180&&r>g+70&&r>b+40)&&HasColor(thumb,(r,g,b)=>b>180&&b>r+70)&&HasColor(thumb,(r,g,b)=>r<50&&g<50&&b<50),"preview contains the real red image, blue diagonal line and black writing, not a count tile");
   check(File.ReadAllBytes(manifest).SequenceEqual(before)&&File.ReadAllBytes(original).SequenceEqual(sourceBytes)&&File.GetLastWriteTimeUtc(original)==sourceTime,"legacy thumbnails never rewrite the project, source bytes or source timestamps");
   using(var stream=File.Open(store.ImagePath(board.Id,picture.Image),FileMode.Open,FileAccess.ReadWrite,FileShare.None))check(stream.Length>0,"detached legacy thumbnail does not retain a project-image file lock");
   var rows=CanvasProjectsPage.QueryProjects(store,mature);check(rows.Count==1&&rows[0].Id==board.Id&&rows[0].Images==1,"shared read-only project query exposes legacy boards for both gallery and destination picker");
   var first=CanvasProjectThumbnail.Read(store,mature,rows[0]);var again=CanvasProjectThumbnail.Read(store,mature,rows[0]);check(ReferenceEquals(first,again)&&CanvasProjectThumbnail.CacheBytesForTests<=CanvasProjectThumbnail.CacheBudget,"unchanged cards reuse bounded decoded thumbnail cache");
   var empty=store.Create("空白画布");check(CanvasProjectThumbnail.Read(store,mature,CanvasProjectsPage.Describe(empty))==null,"empty project has a real empty-state instead of a misleading generated preview");
   int creates=0,opens=0;string opened=null;var page=new CanvasProjectsPage(store,(id,paths)=>{opens++;opened=id;return true;},data=>new string[0],data=>new string[0],()=>true,()=>true,()=>false,message=>{},mature,()=>creates++,true);
   Render(page,870);var button=page.ProjectButtonForTests(board.Id);var other=page.ProjectButtonForTests(empty.Id);check(button!=null&&button.Parent is WrapPanel&&button.Width==252&&button.Height>200,"project gallery is a wrapping thumbnail-card surface rather than full-width metadata rows");
   var boardGrid=(Grid)button.Content;check(boardGrid.RowDefinitions.Count==3&&boardGrid.Children.OfType<Grid>().Any(g=>g.Children.OfType<CanvasProjectThumbnailImage>().Any())&&boardGrid.Children.OfType<TextBlock>().Any(t=>t.Text==board.Name),"each project card places a board thumbnail above its readable project name and date");
   check(Math.Abs(button.TranslatePoint(new Point(),page).Y-other.TranslatePoint(new Point(),page).Y)<1&&Math.Abs(button.TranslatePoint(new Point(),page).X-other.TranslatePoint(new Point(),page).X)>250,"wide project gallery places independent boards side by side");
   Render(page,400);check(Math.Abs(button.TranslatePoint(new Point(),page).X-other.TranslatePoint(new Point(),page).X)<1&&Math.Abs(button.TranslatePoint(new Point(),page).Y-other.TranslatePoint(new Point(),page).Y)>200,"narrow gallery wraps complete thumbnail cards into the next row");
   page.NewCanvasButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(creates==1&&store.List().Count==2,"destination-mode New canvas calls its owner without creating or opening any implicit project");
   button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(opens==1&&opened==board.Id,"thumbnail card selection returns exactly the selected existing project ID");
   string appearance=Theme.Current;try{foreach(string mode in new[]{"light","dark"}){Theme.Set(mode);var gallery=new CanvasProjectsPage(store,(id,paths)=>true,data=>new string[0],data=>new string[0],()=>true,()=>true,()=>false,message=>{},mature);Evidence(gallery,store,mature,Path.Combine(root,"gallery-"+mode+".png"));}}finally{Theme.Set(appearance);}
   var current=mature.Create("成熟画布");string matureManifest=Path.Combine(mature.Root,current.Id,MatureCanvasStore.ManifestName);byte[] matureBefore=File.ReadAllBytes(matureManifest);byte[] png=Png(640,400,Colors.CornflowerBlue);CanvasProjectThumbnail.SaveMature(mature,current,Url(png));var saved=CanvasProjectThumbnail.ReadMature(mature,current.Id);
   check(saved!=null&&saved.PixelWidth<=320&&saved.PixelHeight<=320&&saved.IsFrozen&&HasColor(saved,(r,g,b)=>b>r+50),"saved mature scene PNG is validated, detached and decoded only at gallery size");
   check(File.ReadAllBytes(matureManifest).SequenceEqual(matureBefore),"mature preview is an optional sidecar and never edits scene metadata or timestamps");
   check(CanvasProjectThumbnail.ReadMature(new MatureCanvasStore(Path.Combine(root,"profile")),current.Id)!=null,"mature gallery thumbnail survives a fresh store and process-equivalent reopen");
   string pngPath=Path.Combine(mature.Root,current.Id,CanvasProjectThumbnail.ImageName);byte[] stablePng=File.ReadAllBytes(pngPath);string metaPath=Path.Combine(mature.Root,current.Id,CanvasProjectThumbnail.MetadataName);byte[] stableMeta=File.ReadAllBytes(metaPath);
   check(Reject(()=>CanvasProjectThumbnail.SaveMature(mature,current,"data:image/svg+xml;base64,AAAA"))&&Reject(()=>CanvasProjectThumbnail.SaveMature(mature,current,Url(new byte[]{1,2,3})))&&Reject(()=>CanvasProjectThumbnail.SaveMature(mature,current,Url(Png(641,2,Colors.Red))))&&File.ReadAllBytes(pngPath).SequenceEqual(stablePng)&&File.ReadAllBytes(metaPath).SequenceEqual(stableMeta),"wrong MIME, disguised binary and oversized pixels cannot replace the last good scene preview");
   CanvasProjectThumbnail.SaveMature(mature,current,Url(Png(1,640,Colors.Green)));var narrow=CanvasProjectThumbnail.ReadMature(mature,current.Id);check(narrow!=null&&narrow.PixelWidth<=320&&narrow.PixelHeight<=320,"extreme portrait thumbnails are bounded by their longest edge and never upscaled to giant allocations");
   File.WriteAllBytes(pngPath,png);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)==null,"a torn PNG/metadata pair never displays a mismatched scene preview");
   CanvasProjectThumbnail.SaveMature(mature,current,Url(png));var stale=mature.Load(current.Id);current.Name="新项目名";mature.Save(current);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)!=null&&Reject(()=>CanvasProjectThumbnail.SaveMature(mature,stale,Url(png))),"title-only durable commits preserve preview content while still rejecting exports from an old loaded revision");
   mature.Save(current);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)!=null,"the final unchanged close flush preserves a valid thumbnail instead of discarding it with a fresh manifest timestamp");
   var scene=Obj(Json().DeserializeObject(current.SceneJson));var records=Obj(Obj(scene["document"])["store"]);records["shape:preview-text"]=Map("id","shape:preview-text","typeName","shape","type","text","x",10,"y",20,"rotation",0,"index","a1","parentId","page:page","isLocked",false,"opacity",1,"props",Map("text","预览内容"),"meta",Map());records["page:second"]=Map("id","page:second","typeName","page","name","第二页","index","a2","meta",Map());
   var session=Obj(scene["session"]);var states=(object[])session["pageStates"];session["pageStates"]=states.Concat(new object[]{Map("pageId","page:second","camera",Map("x",0,"y",0,"z",1),"selectedShapeIds",new object[0],"focusedGroupId",null)}).ToArray();current.SceneJson=Json().Serialize(scene);mature.Save(current);
   check(CanvasProjectThumbnail.ReadMature(mature,current.Id)==null,"real scene content additions invalidate the previous thumbnail");CanvasProjectThumbnail.SaveMature(mature,current,Url(png));
   var state=Obj(states[0]);state["camera"]=Map("x",350,"y",-175,"z",2);state["selectedShapeIds"]=new[]{"shape:preview-text"};session["isFocusMode"]=true;session["isToolLocked"]=true;session["isGridMode"]=true;current.SceneJson=Json().Serialize(scene);mature.Save(current);
   check(CanvasProjectThumbnail.ReadMature(mature,current.Id)!=null,"camera, selection, grid and tools visibility changes retain a fitted current-page preview");
   current.SceneJson=Json().Serialize(Reversed(scene));mature.Save(current);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)!=null,"equivalent object-key ordering does not invalidate the rendered-content fingerprint");
   foreach(var pair in new[]{new[]{264.16666666666669m,264.1666666666667m},new[]{1.5040288088824809m,1.504028808882481m},new[]{22.222622780360862m,22.22262278036086m}}){Obj(records["shape:preview-text"])["x"]=pair[0];current.SceneJson=Json().Serialize(scene);mature.Save(current);CanvasProjectThumbnail.SaveMature(mature,current,Url(png));Obj(records["shape:preview-text"])["x"]=pair[1];current.SceneJson=Json().Serialize(scene);mature.Save(current);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)!=null,"browser first-save shortening and Framework decimal conversion retain the same IEEE-754 preview coordinate");}
   Obj(Obj(records["shape:preview-text"])["props"])["text"]="已经修改的内容";current.SceneJson=Json().Serialize(scene);mature.Save(current);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)==null,"editing actual shape text invalidates a previously exported preview");CanvasProjectThumbnail.SaveMature(mature,current,Url(png));
   session["currentPageId"]="page:second";current.SceneJson=Json().Serialize(scene);mature.Save(current);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)==null,"switching the current page invalidates a preview of the previous page");CanvasProjectThumbnail.SaveMature(mature,current,Url(png));
   var oldMetadata=Obj(Json().DeserializeObject(File.ReadAllText(metaPath)));oldMetadata.Remove("ContentHash");File.WriteAllText(metaPath,Json().Serialize(oldMetadata));check(CanvasProjectThumbnail.ReadMature(mature,current.Id)!=null,"legacy thumbnail metadata remains readable while its exact manifest still matches");current.Pinned=!current.Pinned;mature.Save(current);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)==null,"legacy thumbnails without content fingerprints fail safely after any manifest change");
   CanvasProjectThumbnail.SaveMature(mature,current,null);check(CanvasProjectThumbnail.ReadMature(mature,current.Id)==null&&File.Exists(pngPath),"an empty scene atomically clears display metadata without destructively deleting the recoverable prior PNG");
   var queried=CanvasProjectsPage.QueryProjects(store,mature).Single(r=>r.Id==current.Id);check(queried.Name==current.Name&&queried.Updated==current.Updated&&File.ReadAllBytes(manifest).SequenceEqual(before),"shared gallery query prefers mature names and dates without mutating legacy source manifests");
   for(int i=0;i<36;i++){var extra=store.Create("缓存见证 "+i);extra.Items.Add(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="line",X=0,Y=0,EndX=120,EndY=80,Stroke=2,Color="#000000"});store.Save(extra);CanvasProjectThumbnail.Read(store,mature,CanvasProjectsPage.Describe(extra));}
   check(CanvasProjectThumbnail.CacheBytesForTests>CanvasProjectThumbnail.CacheBudget/2&&CanvasProjectThumbnail.CacheBytesForTests<=CanvasProjectThumbnail.CacheBudget,"scrolling through more boards than cache capacity evicts old decoded scenes and stays within the 8 MiB budget");
  }
 }
